	expiry := time.Now().UTC().Add(365 * 24 * time.Hour).Truncate(time.Second)
	input := entitlement.CreateInput{Key: "seats", Quantity: 10, ExpiresAt: expiry}
	const submitters = 32

	var wg sync.WaitGroup
